export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export const uid=(prefix='event')=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
export const routeTemplates={mint:['تحویل','ذوب','نورد','برش','آنیل','ضرب','XRF','کنترل کیفیت','بسته‌بندی'],cast:['تحویل','ذوب','کست','XRF','کنترل کیفیت','بسته‌بندی'],granules:['تحویل','ذوب','تنظیم عیار','گرانول','XRF','تحویل صندوق'],silverRefine:['تحویل','نمونه و XRF','انحلال','کلرید','احیا','ذوب','گرانول','XRF','تحویل صندوق'],electro:['تحویل','آند','الکتروریفاینینگ','کریستال','ذوب','گرانول','XRF','تحویل صندوق'],goldRefine:['تحویل','نمونه و XRF','پالایش','رسوب','ذوب','XRF','کست','تحویل صندوق'],general:['شروع کار','اجرا','تحویل نتیجه']};
export const statusNames={requested:'منتظر تأیید',waiting:'در انتظار',active:'در جریان',paused:'متوقف',done:'به اتمام رسیده',cancelled:'لغوشده'};
export const certaintyNames={unknown:'نامشخص',declared:'اعلامی / شرطی',estimated:'برآوردی',measured:'اندازه‌گیری‌شده',final:'نهایی'};
export const placeNames=['صندوق','ذوب','نورد','ضرب','آزمایشگاه','محلول','فیلتر','کلرید','گرانول','بسته‌بندی','بازیافت','خارج کارخانه'];
export function numberOrNull(v){if(v===null||v===undefined||String(v).trim()==='')return null;const n=parseNumber(v);if(!Number.isFinite(n)||n<0)throw new Error('عدد نامنفی معتبر وارد کنید.');return n;}
const positive=v=>{const n=numberOrNull(v);if(n===null||n<=0)throw new Error('مقدار مثبت لازم است.');return n;};
const required=(value,label='توضیح')=>{const s=String(value??'').trim();if(!s)throw new Error(label+' لازم است.');return s;};
const permitted=(condition)=>{if(!condition)throw new Error('این اقدام در اختیار این حساب نیست.');};
export const operationallyFrozen=s=>s.connection.location==='outside'&&s.connection.sync!=='complete';
